def solve(rows):
    state = 9
    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 13 != 2 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 9
        else:
            state = (3 * state + weight) % 13

    if not kept_rows:
        return [0, None]

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    total_quantity = 0
    earliest_expiry = None
    today = 13

    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            try:
                expiry = int(row[0])
                quantity = int(row[1])
                if expiry > today:
                    total_quantity += quantity
                    if earliest_expiry is None or expiry < earliest_expiry:
                        earliest_expiry = expiry
            except (ValueError, TypeError):
                pass

    return [total_quantity, earliest_expiry]

